package com.infinitylibrary.community;

import com.infinitylibrary.InfinityLibraryPlugin;
import com.infinitylibrary.gui.LibraryMenu;
import io.papermc.paper.registry.data.dialog.input.*;
import net.kyori.adventure.text.Component;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.inventory.*;
import org.bukkit.inventory.meta.BookMeta;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.configuration.file.YamlConfiguration;
import java.nio.file.Path;
import java.util.*;
import java.util.function.UnaryOperator;

public final class CollaborationManager {
    private final InfinityLibraryPlugin plugin;private final Path file;private final Map<UUID,SharedManuscript> docs=new LinkedHashMap<>();
    private final Map<UUID,Integer> cursors=new HashMap<>();
    public CollaborationManager(InfinityLibraryPlugin p){plugin=p;file=p.getDataFolder().toPath().resolve("collaborative-books.yml");load();}
    public void load(){
        var y=AtomicYaml.read(file);Map<UUID,SharedManuscript> loaded=new LinkedHashMap<>();var root=y.getConfigurationSection("manuscripts");
        if(root!=null)for(String key:root.getKeys(false)){var s=root.getConfigurationSection(key);Map<UUID,String> editors=new HashMap<>(),contributors=new HashMap<>();for(String name:List.of("editors","contributors")){var sec=s.getConfigurationSection(name);if(sec!=null)for(String id:sec.getKeys(false))(name.equals("editors")?editors:contributors).put(UUID.fromString(id),sec.getString(id));}SharedManuscript d=new SharedManuscript(UUID.fromString(key),UUID.fromString(s.getString("owner")),s.getString("owner-name"),editors,contributors,s.getLong("revision"),s.getString("title"),s.getString("category","general"),s.getString("tags",""),s.getBoolean("public"),s.getStringList("pages"));loaded.put(d.id(),d);}
        docs.clear();docs.putAll(loaded);cursors.clear();
    }
    public void save(){YamlConfiguration y=new YamlConfiguration();for(var d:docs.values()){var s=y.createSection("manuscripts."+d.id());s.set("owner",d.owner().toString());s.set("owner-name",d.ownerName());s.set("revision",d.revision());s.set("title",d.title());s.set("category",d.category());s.set("tags",d.tags());s.set("public",d.publicBook());s.set("pages",d.pages());d.editors().forEach((id,name)->s.set("editors."+id,name));d.contributors().forEach((id,name)->s.set("contributors."+id,name));}AtomicYaml.write(file,y);}
    public SharedManuscript get(Player p,UUID id){SharedManuscript d=docs.get(id);if(d==null||!d.canEdit(p.getUniqueId()))throw new IllegalArgumentException("Shared manuscript not found or no longer shared with you.");return d;}
    public List<SharedManuscript> visible(Player p){return docs.values().stream().filter(d->d.canEdit(p.getUniqueId())).sorted(Comparator.comparing(SharedManuscript::title).thenComparing(d->d.id().toString())).toList();}
    public SharedManuscript create(Player p,String title){if(docs.values().stream().filter(d->d.owner().equals(p.getUniqueId())).count()>=Math.max(1,plugin.getConfig().getInt("community.max-shared-drafts-per-owner",10)))throw new IllegalArgumentException("Your shared manuscript limit has been reached.");SharedManuscript d=SharedManuscript.create(p.getUniqueId(),p.getName(),title);docs.put(d.id(),d);try{save();}catch(RuntimeException ex){docs.remove(d.id());throw ex;}return d;}
    public SharedManuscript update(Player p,UUID id,UnaryOperator<SharedManuscript> action){SharedManuscript old=get(p,id),next=action.apply(old);docs.put(id,next);try{save();}catch(RuntimeException ex){docs.put(id,old);throw ex;}return next;}
    public void invite(Player p,UUID id,String player){UUID uuid;String name;Player online=Bukkit.getPlayerExact(player);if(online!=null){uuid=online.getUniqueId();name=online.getName();}else{var known=Arrays.stream(Bukkit.getOfflinePlayers()).filter(o->o.getName()!=null&&o.getName().equalsIgnoreCase(player)).findFirst().orElseThrow(()->new IllegalArgumentException("That player must have joined this server before being invited."));uuid=known.getUniqueId();name=known.getName();}UUID selected=uuid;String label=name;update(p,id,d->d.invite(p.getUniqueId(),selected,label));}
    public void revoke(Player p,UUID id,UUID editor){update(p,id,d->d.revoke(p.getUniqueId(),editor));}
    public void delete(Player p,UUID id){SharedManuscript old=get(p,id);old.requireOwner(p.getUniqueId());docs.remove(id);try{save();}catch(RuntimeException ex){docs.put(id,old);throw ex;}}
    public void browser(Player p,int page){var list=visible(p);page=Math.max(0,Math.min(page,Math.max(0,(list.size()-1)/45)));LibraryMenu menu=new LibraryMenu(p,LibraryMenu.Screen.COLLAB_LIST,54,"Library • Shared manuscripts");var w=plugin.getBookWritingManager();for(int i=0;i<45&&page*45+i<list.size();i++){var d=list.get(page*45+i);menu.entry(i,d.id().toString());w.icon(menu.getInventory(),i,Material.WRITABLE_BOOK,"§d"+d.title(),"§7Owner: "+d.ownerName(),"§7Editors: "+d.editors().size()+" · Revision "+d.revision());}menu.entry(53,Integer.toString(page));w.icon(menu.getInventory(),45,Material.ARROW,"Previous");w.icon(menu.getInventory(),47,Material.FEATHER,"Create shared manuscript");w.icon(menu.getInventory(),49,Material.CHEST,"Main menu");w.icon(menu.getInventory(),51,Material.ARROW,"Next");p.openInventory(menu.getInventory());}
    private int cursor(Player p,SharedManuscript d){return Math.max(0,Math.min(cursors.getOrDefault(p.getUniqueId(),0),d.pages().size()-1));}
    public void open(Player p,UUID id){plugin.getNativeBookEditor().cleanup(p);var d=get(p,id);int page=cursor(p,d);LibraryMenu m=new LibraryMenu(p,LibraryMenu.Screen.COLLAB_EDIT,54,"Library • Shared writing desk");m.entry(0,id.toString());m.entry(1,Long.toString(d.revision()));m.entry(2,Integer.toString(page));var w=plugin.getBookWritingManager();Inventory inv=m.getInventory();w.icon(inv,4,Material.ENCHANTED_BOOK,d.title(),"§7Owner: "+d.ownerName(),"§7Revision "+d.revision()+" · "+d.editors().size()+" editor(s)");w.icon(inv,11,Material.NAME_TAG,"Book details");w.icon(inv,13,Material.FEATHER,"Write in Book & Quill");w.icon(inv,20,Material.ARROW,"Previous page");w.icon(inv,22,Material.PAPER,"Page "+(page+1)+" / "+d.pages().size(),"§7"+d.pages().get(page).replace('\n',' ').substring(0,Math.min(70,d.pages().get(page).length())));w.icon(inv,24,Material.ARROW,"Next page");w.icon(inv,29,Material.LIME_DYE,"Insert page");w.icon(inv,31,Material.RED_DYE,"Delete page (confirm)");w.icon(inv,45,Material.CHEST,"Shared manuscripts");w.icon(inv,47,Material.BOOK,"Preview");if(d.owner().equals(p.getUniqueId())){w.icon(inv,15,Material.PLAYER_HEAD,"Invite editor");w.icon(inv,33,Material.IRON_DOOR,"Manage editors");w.icon(inv,51,Material.EMERALD,"Finish book (owner)");w.icon(inv,53,Material.BARRIER,"Delete manuscript (confirm)");}p.openInventory(inv);}
    public void handle(Player p,LibraryMenu m,int slot){var dialogs=plugin.getManagedDialogs();var w=plugin.getBookWritingManager();if(m.screen()==LibraryMenu.Screen.COLLAB_LIST){int page=Integer.parseInt(m.entry(53));if(slot<45&&m.entry(slot)!=null){cursors.put(p.getUniqueId(),0);open(p,UUID.fromString(m.entry(slot)));}else if(slot==45)browser(p,page-1);else if(slot==51)browser(p,page+1);else if(slot==49)plugin.getGuiManager().openMainMenu(p);else if(slot==47)dialogs.form(p,"New shared manuscript",List.of(DialogInput.text("title",Component.text("Title")).maxLength(32).build()),r->{var d=create(p,r.getText("title"));cursors.put(p.getUniqueId(),0);open(p,d.id());},()->browser(p,0));return;}
        UUID id=UUID.fromString(m.entry(0));long revision=Long.parseLong(m.entry(1));int page=Integer.parseInt(m.entry(2));SharedManuscript d=get(p,id);if(m.screen()==LibraryMenu.Screen.COLLAB_PUBLISH){d.requireOwner(p.getUniqueId());d.requireEdit(p.getUniqueId(),revision);if(slot==11||slot==15){w.deliver(p,signed(p,d),slot==15);browser(p,0);}else if(slot==22)open(p,id);return;}
        switch(slot){case 45->browser(p,0);case 20->{cursors.put(p.getUniqueId(),page-1);open(p,id);}case 24->{cursors.put(p.getUniqueId(),page+1);open(p,id);}case 13->plugin.getNativeBookEditor().shared(p,id);
        case 11->dialogs.form(p,"Shared book details",List.of(DialogInput.text("title",Component.text("Title")).maxLength(32).initial(d.title()).build(),DialogInput.text("category",Component.text("Category")).maxLength(64).initial(d.category()).build(),DialogInput.text("tags",Component.text("Tags")).maxLength(256).initial(d.tags()).build(),DialogInput.bool("public",Component.text("Public (owner only)"),d.publicBook(),"true","false")),r->{update(p,id,old->old.details(p.getUniqueId(),revision,r.getText("title"),r.getText("category"),r.getText("tags"),Boolean.TRUE.equals(r.getBoolean("public"))));open(p,id);},()->open(p,id));
        case 29->{update(p,id,old->old.insert(p.getUniqueId(),revision,page));cursors.put(p.getUniqueId(),page+1);open(p,id);}case 31->dialogs.show(p,"Delete shared page?","This removes its saved text.",List.of(),List.of(new ManagedDialogs.Button("Delete page",r->{update(p,id,old->old.removePage(p.getUniqueId(),revision,page));open(p,id);}),new ManagedDialogs.Button("Keep",r->open(p,id))));
        case 47->{p.closeInventory();p.openBook(signedPreview(p,d));}case 15->{d.requireOwner(p.getUniqueId());dialogs.form(p,"Invite an editor",List.of(DialogInput.text("name",Component.text("Player who has joined this server")).maxLength(16).build()),r->{get(p,id).requireEdit(p.getUniqueId(),revision);invite(p,id,r.getText("name"));open(p,id);},()->open(p,id));}
        case 33->{d.requireOwner(p.getUniqueId());List<ManagedDialogs.Button> buttons=new ArrayList<>();for(var member:d.editors().entrySet())if(!member.getKey().equals(d.owner()))buttons.add(new ManagedDialogs.Button("Remove "+member.getValue(),r->{revoke(p,id,member.getKey());open(p,id);}));buttons.add(new ManagedDialogs.Button("Back",r->open(p,id)));dialogs.show(p,"Shared editors","Only the owner may invite/remove editors.",List.of(),buttons);}
        case 51->{d.requireOwner(p.getUniqueId());d.draft().validatePublish();LibraryMenu next=new LibraryMenu(p,LibraryMenu.Screen.COLLAB_PUBLISH,27,"Finish shared book");next.entry(0,id.toString());next.entry(1,Long.toString(d.revision()));next.entry(2,Integer.toString(page));w.icon(next.getInventory(),11,Material.WRITTEN_BOOK,"Sign copy","Costs one blank book & quill");w.icon(next.getInventory(),15,Material.CHISELED_BOOKSHELF,"Publish","Costs one blank book & quill");w.icon(next.getInventory(),22,Material.ARROW,"Back");p.openInventory(next.getInventory());}
        case 53->{d.requireOwner(p.getUniqueId());dialogs.show(p,"Delete shared manuscript?",d.title()+" — this cannot be undone.",List.of(),List.of(new ManagedDialogs.Button("Delete",r->{get(p,id).requireEdit(p.getUniqueId(),revision);delete(p,id);browser(p,0);}),new ManagedDialogs.Button("Keep",r->open(p,id))));}
        }
    }
    private ItemStack signedPreview(Player p,SharedManuscript d){ItemStack item=plugin.getBookWritingManager().book(p,d.draft(),false);BookMeta meta=(BookMeta)item.getItemMeta();meta.setAuthor(d.ownerName());meta.getPersistentDataContainer().set(new NamespacedKey(plugin,"book_owner_uuid"),PersistentDataType.STRING,d.owner().toString());item.setItemMeta(meta);return item;}
    public ItemStack signed(Player p,SharedManuscript d){d.requireOwner(p.getUniqueId());d.draft().validatePublish();ItemStack item=plugin.getBookWritingManager().book(p,d.draft(),true);var meta=item.getItemMeta();String credits=String.join(", ",new TreeSet<>(d.contributors().values()));meta.getPersistentDataContainer().set(new NamespacedKey(plugin,"book_coauthors"),PersistentDataType.STRING,credits);meta.setLore(List.of("§7Contributors: "+credits));item.setItemMeta(meta);return item;}
    public void cleanup(Player p){cursors.remove(p.getUniqueId());}
}
